content.css:
/* Portfolio Drift. Theme tokens arrive as --bf-* on the root (theme.ts). */
.pdr-root {
  box-sizing: border-box;
  height: 100%;
  display: flex;
  flex-direction: column;
  position: relative;
  padding: 4px 6px 24px 6px;
  background: var(--bf-bg);
  color: var(--bf-text);
  overflow: hidden;
  font-family: "Segoe UI", sans-serif;
}
.pdr-root :focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 2px;
}
/* Zero-specificity reset: any class rule (e.g. the suite info button) wins over it. */
:where(.pdr-root button) {
  font: inherit;
  color: inherit;
}
.pdr-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
/* ── Landing (ported from ResourceGapAnalysis, --bf-* tokens) ───────── */
.bfusion-landing-wrap {
  flex: 1;
  min-height: 0;
  width: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: var(--bf-bg);
  overflow: auto;
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: var(--bf-text);
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: var(--bf-muted);
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: var(--bf-text);
}
.bfusion-landing__missing {
  margin: 12px 0 0;
  padding: 4px 10px;
  font-size: 11px;
  line-height: 1.4;
  font-weight: 600;
  color: var(--bf-hint-text);
  background: var(--bf-hint-bg);
  border: 1px solid var(--bf-hint-border);
  border-radius: 4px;
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: var(--bf-rule);
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: var(--bf-muted);
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: var(--bf-muted);
}
/* ── License badge placement (license.ts styles the badge itself) ───── */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
/* ── Header ─────────────────────────────────────────────────────────── */
.pdr-header {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  position: relative;
  padding: 2px 4px 4px;
  min-height: 22px;
}
.pdr-header__titles {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.pdr-header__title {
  font-weight: 600;
  color: var(--bf-text);
}
.pdr-header__subtitle {
  color: var(--bf-muted);
}
.pdr-header__info {
  width: 20px;
  height: 20px;
  flex: none;
  border-radius: 50%;
  border: 1px solid #E3E6EC;
  background: #fff;
  color: #6B7280;
  font-family: inherit;
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  line-height: 1;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: transform 0.12s;
}
.pdr-header__info:hover {
  background: #E8612A;
  color: #fff;
  transform: scale(1.05);
}
.pdr-header__info:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 2px;
}
.pdr-header__info-pop {
  position: absolute;
  right: 4px;
  top: 26px;
  z-index: 5;
  width: 300px;
  max-width: 90%;
  box-sizing: border-box;
  padding: 10px 12px;
  background: var(--bf-surface);
  border: 1px solid var(--bf-rule);
  border-radius: 6px;
  box-shadow: 0 4px 16px var(--bf-shadow);
  font-size: var(--pdr-insight-font, 11px);
  color: var(--bf-text);
}
.pdr-info__title {
  font-weight: 650;
  margin-bottom: 6px;
}
.pdr-info__list {
  margin: 0;
  padding-left: 16px;
}
.pdr-info__list li {
  margin-bottom: 4px;
  color: var(--bf-muted);
}
/* ── Body ───────────────────────────────────────────────────────────── */
.pdr-body {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: row;
  position: relative;
}
.pdr-chart-col {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}
.pdr-chart-wrap {
  flex: 1;
  min-height: 0;
  position: relative;
}
.pdr-chart {
  display: block;
}
.pdr-chart .pdr-bubble {
  cursor: pointer;
}
.pdr-chart .pdr-bubble:focus-visible {
  outline: none;
  stroke: #D97B29;
  stroke-width: 3px;
}
.pdr-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  padding: 2px 4px;
  color: var(--bf-muted);
}
.pdr-legend__item {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.pdr-legend__dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  box-sizing: border-box;
}
.pdr-hint {
  font-size: var(--pdr-player-font, 12px);
  padding: 6px 8px;
  color: var(--bf-hint-text);
  background: var(--bf-hint-bg);
  border: 1px solid var(--bf-hint-border);
  border-radius: 4px;
  margin: 4px;
}
.pdr-message {
  font-size: var(--pdr-insight-font, 11px);
  margin: auto;
  color: var(--bf-muted);
  text-align: center;
  padding: 16px;
}
/* ── Player ─────────────────────────────────────────────────────────── */
.pdr-player {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 4px 2px;
  border-top: 1px solid var(--bf-rule);
}
.pdr-player__btn {
  height: 28px;
  min-width: 28px;
  padding: 0 6px;
  border: 1px solid var(--bf-rule);
  border-radius: 4px;
  background: var(--bf-surface);
  cursor: pointer;
}
.pdr-player__btn:hover {
  border-color: #E8612A;
}
.pdr-player__play {
  min-width: 34px;
}
.pdr-player__track {
  flex: 1;
  min-width: 60px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.pdr-player__scrub {
  width: 100%;
  margin: 0;
  accent-color: #E8612A;
}
.pdr-player__readout {
  text-align: right;
  min-width: 84px;
}
.pdr-player__label {
  font-weight: 600;
}
.pdr-player__counter {
  color: var(--bf-muted);
  font-size: 0.85em;
}
.pdr-strip {
  display: flex;
  gap: 2px;
  height: 14px;
}
.pdr-strip__cell {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  cursor: pointer;
  border-radius: 1px;
}
.pdr-strip__cell:hover {
  background: var(--bf-surface-alt);
}
.pdr-strip__cell.pdr-strip__cell--current {
  outline: 1.5px solid #D97B29;
  outline-offset: 1px;
}
.pdr-strip__off {
  background: #E24B4A;
}
.pdr-strip__risk {
  background: #EF9F27;
}
.pdr-player--narrow .pdr-player__prev,
.pdr-player--narrow .pdr-player__next,
.pdr-player--narrow .pdr-player__speed,
.pdr-player--narrow .pdr-strip,
.pdr-player--narrow .pdr-player__counter {
  display: none;
}
/* ── Insight rail (suite chrome, fixed) ─────────────────────────────── */
.bfusion-insight-strip {
  flex: 0 0 26px;
  width: 26px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding-top: 10px;
  background: #f4f5f7;
  border-left: 1px solid #e5e7eb;
  color: #888;
  cursor: pointer;
  user-select: none;
}
.bfusion-insight-strip:hover {
  background: #eceef1;
  color: #333;
}
.bfusion-insight-strip:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: -2px;
}
.bfusion-insight-strip__arrow {
  font-size: 10px;
  color: #D97B29;
}
.bfusion-insight-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  font-size: 9px;
  font-weight: 650;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: #aaa;
}
/* ── Insight panel ──────────────────────────────────────────────────── */
.pdr-panel {
  flex: 0 0 250px;
  width: 250px;
  max-width: 320px;
  box-sizing: border-box;
  overflow-y: auto;
  padding: 8px 10px;
  font-size: var(--pdr-insight-font, 11px);
  color: var(--bf-text);
  background: linear-gradient(180deg, var(--bf-surface) 0%, var(--bf-surface-alt) 100%);
  border-left: 1px solid var(--bf-rule);
}
.pdr-panel__header {
  border-bottom: 2px solid var(--pdr-insight-accent, #E8612A);
  padding-bottom: 4px;
  margin-bottom: 8px;
}
.pdr-panel__title {
  font-size: var(--pdr-insight-header-font, 13px);
  font-weight: 650;
}
.pdr-panel__count {
  color: var(--bf-muted);
  font-size: calc(var(--pdr-insight-font, 11px) - 1px);
}
.pdr-panel__kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin-bottom: 8px;
}
.pdr-kpi {
  background: var(--bf-tile);
  border-left: 3px solid #ccc;
  padding: 4px 6px;
  border-radius: 0;
}
.pdr-kpi__value {
  font-size: calc(var(--pdr-insight-font, 11px) + 4px);
  font-weight: 650;
}
.pdr-kpi__label {
  color: var(--bf-muted);
}
.pdr-kpi__delta {
  font-size: calc(var(--pdr-insight-font, 11px) - 1px);
}
.pdr-panel__health {
  display: flex;
  height: 6px;
  border-radius: 3px;
  overflow: hidden;
  margin-bottom: 10px;
  background: var(--bf-rule);
}
.pdr-panel__sectiontitle {
  font-weight: 650;
  margin: 8px 0 4px;
  color: var(--bf-muted);
  font-size: calc(var(--pdr-insight-font, 11px) - 1px);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.pdr-smart {
  list-style: none;
  margin: 0;
  padding: 0;
}
.pdr-smart__item {
  border-left: 3px solid #ccc;
  padding: 2px 0 2px 6px;
  margin-bottom: 6px;
  line-height: 1.35;
}
.pdr-smart__item strong {
  font-weight: 700;
}
.pdr-smart__health {
  font-weight: 600;
}
.pdr-smart__item--link {
  cursor: pointer;
}
.pdr-smart__item--link:hover {
  background: var(--bf-surface-alt);
}
.pdr-list__row {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 2px 0;
  cursor: pointer;
}
.pdr-list__row:hover {
  background: var(--bf-surface-alt);
}
.pdr-list__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex: none;
}
.pdr-list__name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pdr-list__val {
  color: var(--bf-muted);
  font-variant-numeric: tabular-nums;
}
/* ── Width classes (no @media: the iframe viewport is not the visual) ── */
.pdr-root.pdr-medium .pdr-panel {
  flex-basis: 200px;
  width: 200px;
}
.pdr-root.pdr-narrow .pdr-panel {
  position: absolute;
  right: 26px;
  top: 0;
  bottom: 0;
  z-index: 4;
  box-shadow: -4px 0 12px var(--bf-shadow);
}
.pdr-root.pdr-narrow .pdr-legend {
  display: none;
}
